import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { FaGraduationCap, FaSignOutAlt, FaUserCircle, FaBars } from 'react-icons/fa';
import { useAuth } from '../../context/AuthContext';
import NotificationBell from './NotificationBell';
import './Navbar.css';

const Navbar = ({ onToggleSidebar }) => {
  const { user, isAuthenticated, logout } = useAuth();
  const navigate = useNavigate();

  const handleLogout = () => {
    logout();
    navigate('/');
  };

  const getRoleBadgeClass = (role) => {
    switch (role) {
      case 'admin':
        return 'badge-danger';
      case 'teacher':
        return 'badge-warning';
      case 'student':
        return 'badge-primary';
      default:
        return 'badge-info';
    }
  };

  return (
    <nav className="navbar">
      <div className="navbar-container">
        <div className="navbar-left">
          {isAuthenticated && onToggleSidebar && (
            <button
              type="button"
              className="navbar-toggle-btn"
              onClick={onToggleSidebar}
              aria-label="Toggle Sidebar"
            >
              <FaBars />
            </button>
          )}
          <Link to="/" className="navbar-brand">
            <div className="navbar-logo">
              <FaGraduationCap />
            </div>
            <div className="navbar-title-box">
              <span className="navbar-title">UniEvents</span>
              <span className="navbar-subtitle">University Event Management System</span>
            </div>
          </Link>
        </div>

        <div className="navbar-right">
          {isAuthenticated && user ? (
            <div className="navbar-user-section">
              <NotificationBell />

              <div className="navbar-user-info">
                <div className="user-avatar-circle">
                  <FaUserCircle />
                </div>
                <div className="user-details">
                  <span className="user-name">
                    {user.profile?.fullName || user.email?.split('@')[0] || 'User'}
                  </span>
                  <span className={`badge ${getRoleBadgeClass(user.role)} user-role-badge`}>
                    {user.role}
                  </span>
                </div>
              </div>

              <button
                type="button"
                className="btn btn-outline navbar-logout-btn"
                onClick={handleLogout}
                title="Logout"
              >
                <FaSignOutAlt />
                <span className="logout-text">Logout</span>
              </button>
            </div>
          ) : (
            <div className="navbar-auth-links">
              <Link to="/student/login" className="btn btn-outline btn-sm">
                Student
              </Link>
              <Link to="/teacher/login" className="btn btn-outline btn-sm">
                Teacher
              </Link>
              <Link to="/admin/login" className="btn btn-primary btn-sm">
                Admin
              </Link>
            </div>
          )}
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
